#include <bits/stdc++.h>
using namespace std;
using ll = long long;
using PII = pair<int, int>;

struct Edge {
    int to;
    ll cap;
    ll flow;
    int rev;
    Edge(int t, ll c, int r) : to(t), cap(c), flow(0), rev(r) {}
};

class DinicFlow {
public:
    int n, s, t;
    vector<vector<Edge>> g;
    vector<int> lev, cur;

    DinicFlow(int nodes, int src, int dst) : n(nodes), s(src), t(dst) {
        g.resize(n);
        lev.resize(n);
        cur.resize(n);
    }

    void connect(int u, int v, ll capacity) {
        g[u].emplace_back(v, capacity, g[v].size());
        g[v].emplace_back(u, 0, g[u].size() - 1);
    }

    bool bfs() {
        fill(lev.begin(), lev.end(), -1);
        queue<int> q;
        lev[s] = 0;
        q.push(s);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (auto& e : g[u]) {
                if (e.cap - e.flow > 0 && lev[e.to] == -1) {
                    lev[e.to] = lev[u] + 1;
                    q.push(e.to);
                }
            }
        }
        return lev[t] != -1;
    }

    ll dfs(int u, ll flow) {
        if (u == t) return flow;
        for (int& i = cur[u]; i < (int)g[u].size(); ++i) {
            Edge& e = g[u][i];
            if (lev[e.to] == lev[u] + 1 && e.cap - e.flow > 0) {
                ll pushed = dfs(e.to, min(flow, e.cap - e.flow));
                if (pushed > 0) {
                    e.flow += pushed;
                    g[e.to][e.rev].flow -= pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

    ll max_flow() {
        ll result = 0;
        while (bfs()) {
            fill(cur.begin(), cur.end(), 0);
            while (ll pushed = dfs(s, numeric_limits<ll>::max())) {
                result += pushed;
            }
        }
        return result;
    }
};

int fireDist[150][150];
int reachDist[150][150];
int cellIdx[150][150];
int n, T;
vector<string> board, caps;

vector<PII> adj(int r, int c) {
    vector<PII> res;
    if (r + 1 < n) res.push_back({r + 1, c});
    if (r - 1 >= 0) res.push_back({r - 1, c});
    if (c + 1 < n) res.push_back({r, c + 1});
    if (c - 1 >= 0) res.push_back({r, c - 1});
    return res;
}

void fireBFS(int sr, int sc) {
    memset(fireDist, -1, sizeof(fireDist));
    queue<PII> q;
    fireDist[sr][sc] = 0;
    q.push({sr, sc});
    while (!q.empty()) {
        auto [r, c] = q.front(); q.pop();
        for (auto [nr, nc] : adj(r, c)) {
            char ch = board[nr][nc];
            if ((ch != 'Z' && !isdigit(ch)) || fireDist[nr][nc] != -1) continue;
            fireDist[nr][nc] = fireDist[r][c] + 1;
            q.push({nr, nc});
        }
    }
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (isdigit(board[i][j]) && fireDist[i][j] == -1)
                fireDist[i][j] = T;
}

void reachBFS(int sr, int sc) {
    memset(reachDist, -1, sizeof(reachDist));
    queue<PII> q;
    reachDist[sr][sc] = 0;
    q.push({sr, sc});
    while (!q.empty()) {
        auto [r, c] = q.front(); q.pop();
        for (auto [nr, nc] : adj(r, c)) {
            if (!isdigit(board[nr][nc]) || reachDist[nr][nc] != -1) continue;
            reachDist[nr][nc] = reachDist[r][c] + 1;
            q.push({nr, nc});
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> T;
    board.resize(n);
    caps.resize(n);
    for (int i = 0; i < n; ++i) cin >> board[i];
    for (int i = 0; i < n; ++i) cin >> caps[i];

    int fireR = -1, fireC = -1;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            cellIdx[i][j] = i * n + j + 1;
            if (board[i][j] == 'Z') {
                fireR = i;
                fireC = j;
            }
        }
    }

    fireBFS(fireR, fireC);

    int totalNodes = 2 * n * n + 2;
    DinicFlow flowNet(totalNodes, 0, totalNodes - 1);

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (isdigit(board[i][j])) {
                int people = board[i][j] - '0';
                flowNet.connect(0, cellIdx[i][j], people);
                reachBFS(i, j);
                for (int r = 0; r < n; ++r) {
                    for (int c = 0; c < n; ++c) {
                        if (isdigit(caps[r][c]) && reachDist[r][c] != -1 &&
                            reachDist[r][c] <= fireDist[r][c] && reachDist[r][c] <= T) {
                            bool ok = true;
                            if (reachDist[r][c] == fireDist[r][c]) {
                                ok = false;
                                for (auto [nr, nc] : adj(r, c)) {
                                    if (reachDist[nr][nc] != -1 &&
                                        reachDist[nr][nc] < fireDist[nr][nc]) {
                                        ok = true;
                                        break;
                                    }
                                }
                            }
                            if (ok) {
                                flowNet.connect(cellIdx[i][j], n * n + cellIdx[r][c], people);
                            }
                        }
                    }
                }
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (isdigit(caps[i][j])) {
                int cap = caps[i][j] - '0';
                flowNet.connect(n * n + cellIdx[i][j], totalNodes - 1, cap);
            }
        }
    }

    cout << flowNet.max_flow() << '\n';
}
